public class Driver { static class Cinema{int seats=5;synchronized void book(String who){if(seats>0)System.out.println("Seat booked for "+who+" | Seats remaining: "+(--seats));else System.out.println("Sold out! Booking rejected for "+who);}}public static void main(String[]a)throws InterruptedException{Cinema c=new Cinema();Thread[] t=new Thread[8];for(int i=0;i<t.length;i++){String n="User-"+(i+1);t[i]=new Thread(()->c.book(n));t[i].start();}for(Thread x:t)x.join();}}
